Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Line distance from center, d/r: <output id="lineOffsetVal">1.25</output><input id="lineOffsetInput" type="range" min="0" max="1.5" step="0.01" value="1.25" oninput="document.getElementById('lineOffsetVal').value=this.value;update_lineOffset(+this.value)"></label>
