// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 900, 600);
draw.rect(900, 600).fill('#ffffff');

var blue = '#0b73a0';
var orange = '#ff6600';
var green = '#00a51b';
var red = '#ff0000';
var black = '#111111';

var topGroup = draw.group();
var dynamicGroup = draw.group();
var topHighlights = [];
var currentD = 1.25;
var viewMode = 'Geometric';
var caseStates = ['noSolution', 'tangent', 'secant'];
var caseIndex = 0;
var demoIndex = 0;

var demoSteps = [
  {
    title: 'Exterior line: no solution',
    narration: 'The line misses the circle entirely. Geometrically, its distance from the center is larger than the radius, so the system has no shared point.',
    state: { lineOffset: 1.25, solutionCase: 'noSolution', viewMode: 'Geometric' }
  },
  {
    title: 'Tangent line: one solution',
    narration: 'Slide the line inward until it just touches the circle. At exactly d = r, the line touches the circle at one point, so the system has one solution.',
    state: { lineOffset: 1, solutionCase: 'tangent', viewMode: 'Geometric' }
  },
  {
    title: 'Secant line: two solutions',
    narration: 'Move the line closer to the center. Once d < r, the line enters and exits the circle, producing two intersection points.',
    state: { lineOffset: 0.55, solutionCase: 'secant', viewMode: 'Geometric' }
  },
  {
    title: 'Connect the picture to algebra',
    narration: 'Switch to the equation view to see the same classification as a discriminant test after substituting the line equation into the circle equation.',
    state: { lineOffset: 0.55, solutionCase: 'secant', viewMode: 'Equation' }
  }
];

function addHaloText(g, str, x, y, size, anchor, fill, family) {
  return g.text(str)
    .attr({ x: x, y: y, 'text-anchor': anchor || 'middle', 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 4, 'stroke-linejoin': 'round' })
    .font({ family: family || 'Georgia, serif', size: size })
    .fill(fill || '#111111');
}

function arrowLine(g, x1, y1, x2, y2, color, width, headLen, headWid) {
  color = color || blue;
  width = width || 3;
  headLen = headLen || 20;
  headWid = headWid || 9;
  var dx = x2 - x1, dy = y2 - y1;
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var px = -uy, py = ux;
  var line = g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });
  var endPts = [
    [x2, y2],
    [x2 - ux * headLen + px * headWid, y2 - uy * headLen + py * headWid],
    [x2 - ux * headLen - px * headWid, y2 - uy * headLen - py * headWid]
  ];
  var startPts = [
    [x1, y1],
    [x1 + ux * headLen + px * headWid, y1 + uy * headLen + py * headWid],
    [x1 + ux * headLen - px * headWid, y1 + uy * headLen - py * headWid]
  ];
  var p1 = g.polygon(endPts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
  var p2 = g.polygon(startPts.map(function (p) { return p[0] + ',' + p[1]; }).join(' ')).fill(color).stroke('none');
  var hit = g.line(x1, y1, x2, y2).stroke({ color: '#ffffff', width: 18, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('This blue line continues infinitely in both directions.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Line', 'The arrowheads remind us that a line is not just the drawn segment. We count every point where the infinite line and circle have the same coordinates.'); });
  return { line: line, end: p1, start: p2, hit: hit };
}

function drawDot(g, x, y, r, label) {
  var d = g.circle(2 * r).center(x, y).fill(black).stroke({ color: '#ffffff', width: 1.5 });
  d.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(label || 'Intersection point', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Intersection point', 'A black dot marks a point that lies on both the circle and the line, so it is a solution of the system.'); });
  return d;
}

function drawMiniPanels() {
  topGroup.clear();

  var panels = [
    { x: 160, y: 118, r: 82, color: orange, label: 'No solutions' },
    { x: 450, y: 118, r: 82, color: green, label: 'One solution' },
    { x: 740, y: 118, r: 82, color: red, label: 'Two solutions' }
  ];

  for (var i = 0; i < panels.length; i++) {
    var h = topGroup.rect(245, 260).move(panels[i].x - 122.5, 10)
      .fill({ color: '#fff7dd', opacity: 0 })
      .stroke({ color: '#222222', width: 0, opacity: 0 });
    topHighlights.push(h);
  }

  var p = panels[0];
  topGroup.circle(2 * p.r).center(p.x, p.y).fill('none').stroke({ color: p.color, width: 2.5 });
  arrowLine(topGroup, 8, 184, 130, -6, blue, 2.5, 17, 7);
  addHaloText(topGroup, p.label, p.x, 258, 28, 'middle', '#111111');

  p = panels[1];
  topGroup.circle(2 * p.r).center(p.x, p.y).fill('none').stroke({ color: p.color, width: 2.5 });
  var u = { x: 0.4472, y: -0.8944 };
  var n = { x: -0.8944, y: -0.4472 };
  var tp = { x: p.x + n.x * p.r, y: p.y + n.y * p.r };
  arrowLine(topGroup, tp.x - u.x * 138, tp.y - u.y * 138, tp.x + u.x * 138, tp.y + u.y * 138, blue, 2.5, 17, 7);
  drawDot(topGroup, tp.x, tp.y, 4.5, 'The tangent point is the single solution.');
  addHaloText(topGroup, p.label, p.x, 258, 28, 'middle', '#111111');

  p = panels[2];
  topGroup.circle(2 * p.r).center(p.x, p.y).fill('none').stroke({ color: p.color, width: 2.5 });
  var dMini = 0.43 * p.r;
  var fp = { x: p.x + n.x * dMini, y: p.y + n.y * dMini };
  arrowLine(topGroup, fp.x - u.x * 158, fp.y - u.y * 158, fp.x + u.x * 158, fp.y + u.y * 158, blue, 2.5, 17, 7);
  var tMini = Math.sqrt(p.r * p.r - dMini * dMini);
  drawDot(topGroup, fp.x + u.x * tMini, fp.y + u.y * tMini, 4.5, 'Upper intersection: one solution point.');
  drawDot(topGroup, fp.x - u.x * tMini, fp.y - u.y * tMini, 4.2, 'Lower intersection: the second solution point.');
  addHaloText(topGroup, p.label, p.x, 258, 28, 'middle', '#111111');

  topGroup.line(45, 292, 855, 292).stroke({ color: '#e5e5e5', width: 1 });
}

function classify(d) {
  if (d > 1.005) return 'no';
  if (Math.abs(d - 1) <= 0.005) return 'tangent';
  return 'two';
}

function classInfo(d) {
  var c = classify(d);
  if (c === 'no') return { count: 0, color: orange, label: 'No solutions', compare: 'd > r', disc: 'Δ < 0' };
  if (c === 'tangent') return { count: 1, color: green, label: 'One solution', compare: 'd = r', disc: 'Δ = 0' };
  return { count: 2, color: red, label: 'Two solutions', compare: 'd < r', disc: 'Δ > 0' };
}

function updateTopHighlight() {
  var c = classify(currentD);
  var active = c === 'no' ? 0 : (c === 'tangent' ? 1 : 2);
  for (var i = 0; i < topHighlights.length; i++) {
    topHighlights[i].fill({ color: '#fff2b8', opacity: i === active ? 0.28 : 0 });
    topHighlights[i].stroke({ color: i === active ? '#d0a000' : '#222222', width: i === active ? 1.5 : 0, opacity: i === active ? 0.75 : 0 });
  }
}

function render() {
  dynamicGroup.clear();
  updateTopHighlight();
  if (viewMode === 'Equation') renderEquationMode();
  else renderGeometryMode();
}

function renderGeometryMode() {
  var g = dynamicGroup.group();
  var info = classInfo(currentD);

  g.rect(850, 270).move(25, 310).rx(10).fill('#ffffff').stroke({ color: '#ededed', width: 1 });
  addHaloText(g, info.label, 455, 338, 27, 'middle', info.color);
  addHaloText(g, info.compare + '  →  ' + info.label.toLowerCase(), 455, 570, 20, 'middle', '#333333', 'Arial, sans-serif');

  var cx = 320, cy = 450, R = 86;
  var ux = 0.496, uy = -0.868;
  var nx = -0.868, ny = -0.496;
  var drawD = Math.abs(currentD - 1) <= 0.005 ? 1 : currentD;
  var foot = { x: cx + nx * drawD * R, y: cy + ny * drawD * R };
  var rPoint = { x: cx + nx * R, y: cy + ny * R };

  var circle = g.circle(2 * R).center(cx, cy).fill('none').stroke({ color: info.color, width: 4 });
  circle.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Circle: x² + y² = r². The radius r is fixed.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Circle', 'The circle stays fixed while the line slides parallel to itself. The only comparison that matters is the perpendicular distance d from the center to the line versus the radius r.'); });

  arrowLine(g, foot.x - ux * 210, foot.y - uy * 210, foot.x + ux * 210, foot.y + uy * 210, blue, 3.5, 22, 10);

  g.line(cx, cy, rPoint.x, rPoint.y).stroke({ color: '#777777', width: 2.5, linecap: 'round' });
  addHaloText(g, 'r', (cx + rPoint.x) / 2 - 15, (cy + rPoint.y) / 2 - 8, 18, 'middle', '#555555', 'Arial, sans-serif');

  var dSeg = g.line(cx, cy, foot.x, foot.y).stroke({ color: '#8a5a00', width: 3, dasharray: '7,5', linecap: 'round' });
  dSeg.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Perpendicular distance d from center to line.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Distance d', 'The dashed segment is perpendicular to the line, so it is the shortest distance from the circle’s center to the line. Compare this length with r to know the number of intersections.'); });
  addHaloText(g, 'd', (cx + foot.x) / 2 + 16, (cy + foot.y) / 2 + 3, 18, 'middle', '#8a5a00', 'Arial, sans-serif');

  g.circle(9).center(cx, cy).fill('#444444');
  addHaloText(g, 'center', cx + 55, cy + 12, 14, 'middle', '#444444', 'Arial, sans-serif');

  if (info.count > 0) {
    var chord = Math.sqrt(Math.max(0, R * R - Math.pow(drawD * R, 2)));
    if (info.count === 1) {
      drawDot(g, foot.x, foot.y, 6, 'Tangent point: the only solution.');
    } else {
      drawDot(g, foot.x + ux * chord, foot.y + uy * chord, 6, 'One of the two intersection points.');
      drawDot(g, foot.x - ux * chord, foot.y - uy * chord, 6, 'The other intersection point.');
    }
  }

  var bx = 615, by = 382;
  g.rect(205, 128).move(bx - 20, by - 30).rx(8).fill('#f8fbff').stroke({ color: '#d8e6f2', width: 1.5 });
  addHaloText(g, 'One comparison', bx + 82, by - 4, 18, 'middle', '#222222', 'Arial, sans-serif');
  addHaloText(g, 'd > r: 0 points', bx + 82, by + 28, 16, 'middle', orange, 'Arial, sans-serif');
  addHaloText(g, 'd = r: 1 point', bx + 82, by + 56, 16, 'middle', green, 'Arial, sans-serif');
  addHaloText(g, 'd < r: 2 points', bx + 82, by + 84, 16, 'middle', red, 'Arial, sans-serif');
}

function formatNum(x) {
  var s = (Math.round(x * 100) / 100).toFixed(2);
  return s.replace(/\.00$/, '');
}

function renderEquationMode() {
  var g = dynamicGroup.group();
  var info = classInfo(currentD);
  var m = 1.70;
  var r = 1;
  var d = currentD;
  var b = d * Math.sqrt(1 + m * m);
  var A = 1 + m * m;
  var B = 2 * m * b;
  var C = b * b - r * r;
  var Delta = B * B - 4 * A * C;

  g.rect(850, 270).move(25, 310).rx(10).fill('#ffffff').stroke({ color: '#ededed', width: 1 });
  g.rect(690, 220).move(105, 332).rx(12).fill('#fbfbfb').stroke({ color: '#d7d7d7', width: 1.5 });

  addHaloText(g, 'Equation view: the same count appears in the discriminant', 450, 360, 19, 'middle', '#222222', 'Arial, sans-serif');

  var x0 = 145, y0 = 400;
  addHaloText(g, 'Circle:', x0, y0, 18, 'start', '#555555', 'Arial, sans-serif');
  addHaloText(g, 'x² + y² = r²', x0 + 95, y0, 20, 'start', '#111111', 'Georgia, serif');

  addHaloText(g, 'Line:', x0, y0 + 36, 18, 'start', '#555555', 'Arial, sans-serif');
  addHaloText(g, 'y = mx + b', x0 + 95, y0 + 36, 20, 'start', '#111111', 'Georgia, serif');

  addHaloText(g, 'Substitute:', x0, y0 + 78, 18, 'start', '#555555', 'Arial, sans-serif');
  addHaloText(g, '(1 + m²)x² + 2mbx + (b² − r²) = 0', x0 + 95, y0 + 78, 19, 'start', '#111111', 'Georgia, serif');

  addHaloText(g, 'Here:', x0, y0 + 118, 18, 'start', '#555555', 'Arial, sans-serif');
  addHaloText(g, formatNum(A) + 'x² + ' + formatNum(B) + 'x + ' + formatNum(C) + ' = 0', x0 + 95, y0 + 118, 19, 'start', '#111111', 'Georgia, serif');

  g.line(580, 388, 580, 525).stroke({ color: '#dddddd', width: 1 });
  addHaloText(g, info.disc, 685, 432, 48, 'middle', info.color, 'Georgia, serif');
  addHaloText(g, 'Δ ≈ ' + formatNum(Delta), 685, 474, 18, 'middle', '#333333', 'Arial, sans-serif');
  addHaloText(g, info.label, 685, 510, 22, 'middle', info.color, 'Arial, sans-serif');

  var hit = g.rect(690, 220).move(105, 332).fill({ color: '#ffffff', opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('Algebra and geometry agree: Δ < 0, = 0, or > 0 gives 0, 1, or 2 real intersections.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () { showPopup('Discriminant test', 'Substituting y = mx + b into x² + y² = r² creates a quadratic in x. Its discriminant tells how many real intersection points the line and circle share.'); });
}

function syncSlider(v) {
  var input = document.getElementById('lineOffsetInput');
  var out = document.getElementById('lineOffsetVal');
  if (input) input.value = String(v);
  if (out) out.value = String(v);
}

function update_lineOffset(v) {
  currentD = Math.max(0, Math.min(1.5, v));
  var c = classify(currentD);
  caseIndex = c === 'no' ? 0 : (c === 'tangent' ? 1 : 2);
  render();
}

function setSolutionCase(name, shouldRender) {
  var d = 1.25;
  if (name === 'tangent') d = 1;
  if (name === 'secant') d = 0.55;
  caseIndex = caseStates.indexOf(name);
  if (caseIndex < 0) caseIndex = 0;
  currentD = d;
  syncSlider(d);
  if (shouldRender !== false) render();
}

function trigger_solutionCase() {
  caseIndex = (caseIndex + 1) % caseStates.length;
  setSolutionCase(caseStates[caseIndex], true);
}

function toggle_viewMode(on) {
  viewMode = on ? 'Equation' : 'Geometric';
  render();
}

function applyStep(i) {
  demoIndex = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[demoIndex];
  var state = step.state || {};

  if (state.solutionCase) setSolutionCase(state.solutionCase, false);
  if (state.lineOffset != null) {
    currentD = +state.lineOffset;
    syncSlider(currentD);
    var c = classify(currentD);
    caseIndex = c === 'no' ? 0 : (c === 'tangent' ? 1 : 2);
  }
  if (state.viewMode) {
    viewMode = state.viewMode;
    var chk = document.getElementById('viewModeInput');
    if (chk) chk.checked = viewMode === 'Equation';
  }

  var n = document.getElementById('demoNarration');
  if (n) n.textContent = step.narration;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
  render();
}

function prevStep() {
  applyStep((demoIndex - 1 + demoSteps.length) % demoSteps.length);
}

function nextStep() {
  applyStep((demoIndex + 1) % demoSteps.length);
}

drawMiniPanels();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

