Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Optional explanation <select id="explanationModeInput" onchange="update_explanationMode(this.value)"><option value="Off" selected>Off</option><option value="Distance comparison">Distance comparison</option><option value="Algebra connection">Algebra connection</option></select></label>
