// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 725, 260);
draw.rect(725, 260).fill('#ffffff');

var baseGroup = draw.group();
var overlayGroup = draw.group();

var BLUE = '#00749b';
var ORANGE = '#ff6600';
var GREEN = '#00a51b';
var RED = '#ff0000';
var BLACK = '#111111';

var currentMode = 'Off';
var demoIndex = 0;

var demoSteps = [
  {
    title: 'Original three-case view',
    narration: 'The default view matches the textbook figure: three side-by-side diagrams showing no intersection, one tangent intersection, and two secant intersections.',
    state: { explanationMode: 'Off' }
  },
  {
    title: 'Optional distance comparison',
    narration: 'Opening the distance overlay adds the center, radius, and perpendicular distance only as an explanation layer: d > r gives no solutions, d = r gives one, and d < r gives two.',
    state: { explanationMode: 'Distance comparison' }
  },
  {
    title: 'Optional algebra connection',
    narration: 'Opening the algebra overlay connects the same three pictures to the discriminant after substituting the line equation into the circle equation.',
    state: { explanationMode: 'Algebra connection' }
  }
];

var panels = [
  {
    key: 'none',
    cx: 132, cy: 113, r: 82, color: ORANGE, label: 'No solutions',
    lineA: { x: 2, y: 124 }, lineB: { x: 101, y: 0 },
    tooltip: 'Exterior line: the line misses the circle, so there are zero shared points.'
  },
  {
    key: 'tangent',
    cx: 400, cy: 113, r: 82, color: GREEN, label: 'One solution',
    lineA: { x: 260, y: 219 }, lineB: { x: 363, y: 0 },
    tooltip: 'Tangent line: the line touches the circle at exactly one point.'
  },
  {
    key: 'secant',
    cx: 630, cy: 113, r: 82, color: RED, label: 'Two solutions',
    lineA: { x: 596, y: 219 }, lineB: { x: 722, y: 0 },
    tooltip: 'Secant line: the line crosses the circle, so there are two shared points.'
  }
];

function unitFromLine(a, b) {
  var dx = b.x - a.x;
  var dy = b.y - a.y;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  return { x: dx / len, y: dy / len };
}

function pointString(points) {
  return points.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function drawDoubleArrow(g, x1, y1, x2, y2, color, width) {
  var dx = x2 - x1, dy = y2 - y1;
  var L = Math.sqrt(dx * dx + dy * dy) || 1;
  var ux = dx / L, uy = dy / L;
  var px = -uy, py = ux;
  var headLen = 13;
  var headWid = 5.5;

  g.line(x1, y1, x2, y2).stroke({ color: color, width: width, linecap: 'round' });

  g.polygon(pointString([
    [x2, y2],
    [x2 - ux * headLen + px * headWid, y2 - uy * headLen + py * headWid],
    [x2 - ux * headLen - px * headWid, y2 - uy * headLen - py * headWid]
  ])).fill(color).stroke('none');

  g.polygon(pointString([
    [x1, y1],
    [x1 + ux * headLen + px * headWid, y1 + uy * headLen + py * headWid],
    [x1 + ux * headLen - px * headWid, y1 + uy * headLen - py * headWid]
  ])).fill(color).stroke('none');

  return g.line(x1, y1, x2, y2)
    .stroke({ color: '#ffffff', width: 16, opacity: 0 })
    .css('cursor', 'pointer');
}

function addLabel(g, str, x, y, size, color) {
  return g.text(str)
    .attr({ x: x, y: y, 'text-anchor': 'middle' })
    .font({ family: 'Georgia, "Times New Roman", serif', size: size })
    .fill(color || BLACK);
}

function addHaloText(g, str, x, y, size, anchor, color, family) {
  return g.text(str)
    .attr({
      x: x,
      y: y,
      'text-anchor': anchor || 'middle',
      'paint-order': 'stroke',
      stroke: '#ffffff',
      'stroke-width': 4,
      'stroke-linejoin': 'round'
    })
    .font({ family: family || 'Arial, sans-serif', size: size })
    .fill(color || BLACK);
}

function drawDot(g, x, y, r, tooltipText) {
  var dot = g.circle(2 * r).center(x, y).fill('#1a1a1a').stroke({ color: '#ffffff', width: 0.8 });
  dot.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tooltipText, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Intersection point', 'A black dot marks a point that lies on both the circle and the line. Each such point is one solution of the circle-line system.');
    });
  return dot;
}

function footOnLine(panel) {
  var u = unitFromLine(panel.lineA, panel.lineB);
  var vx = panel.cx - panel.lineA.x;
  var vy = panel.cy - panel.lineA.y;
  var t = vx * u.x + vy * u.y;
  return { x: panel.lineA.x + u.x * t, y: panel.lineA.y + u.y * t, u: u };
}

function intersections(panel) {
  var f = footOnLine(panel);
  var dx = f.x - panel.cx;
  var dy = f.y - panel.cy;
  var d = Math.sqrt(dx * dx + dy * dy);
  var h = Math.sqrt(Math.max(0, panel.r * panel.r - d * d));
  if (d > panel.r + 0.01) return [];
  if (Math.abs(d - panel.r) < 0.9) return [{ x: f.x, y: f.y }];
  return [
    { x: f.x + f.u.x * h, y: f.y + f.u.y * h },
    { x: f.x - f.u.x * h, y: f.y - f.u.y * h }
  ];
}

function drawBase() {
  baseGroup.clear();
  var labelLayer = baseGroup.group();

  panels.forEach(function (p) {
    var circle = baseGroup.circle(2 * p.r).center(p.cx, p.cy)
      .fill('none')
      .stroke({ color: p.color, width: 2.2 });

    baseGroup.circle(2 * p.r).center(p.cx, p.cy)
      .fill('none')
      .stroke({ color: '#ffffff', width: 14, opacity: 0 })
      .css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(p.tooltip, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        showPopup(p.label, 'The number of black intersection dots is the number of solutions: missing means 0, touching means 1, and crossing means 2.');
      });

    var hit = drawDoubleArrow(baseGroup, p.lineA.x, p.lineA.y, p.lineB.x, p.lineB.y, BLUE, 2.15);
    hit.on('mousemove', function (e) { showTooltip('The blue line continues infinitely in both directions.', e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        showPopup('Line and circle', 'A solution is any point that belongs to both the infinite line and the circle. The arrows indicate the drawn segment is only part of the full line.');
      });

    intersections(p).forEach(function (q, i) {
      var name = p.key === 'tangent' ? 'The single tangent point.' : (i === 0 ? 'Upper-right intersection point.' : 'Lower-left intersection point.');
      drawDot(baseGroup, q.x, q.y, 3.6, name);
    });

    labelLayer.add(addLabel(labelLayer, p.label, p.cx, 248, 24, BLACK));
  });
}

function drawDistanceOverlay() {
  overlayGroup.clear();

  var card = overlayGroup.rect(705, 38).move(10, 6).rx(8)
    .fill({ color: '#fffdf0', opacity: 0.78 })
    .stroke({ color: '#eadb8a', width: 1 });
  card.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Compare the perpendicular distance d from the circle center to the line with the radius r.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Distance comparison', 'If the line is farther than one radius from the center, it misses the circle. If the distance equals the radius it is tangent, and if the distance is smaller it cuts through the circle.');
    });
  addHaloText(overlayGroup, 'Distance test:  d > r  →  0 solutions      d = r  →  1 solution      d < r  →  2 solutions', 362.5, 30, 15, 'middle', '#333333');

  panels.forEach(function (p) {
    var f = footOnLine(p);
    var vx = f.x - p.cx, vy = f.y - p.cy;
    var d = Math.sqrt(vx * vx + vy * vy) || 1;
    var nx = vx / d, ny = vy / d;
    var rPoint = { x: p.cx + nx * p.r, y: p.cy + ny * p.r };

    overlayGroup.circle(5.2).center(p.cx, p.cy).fill('#555555');

    overlayGroup.line(p.cx, p.cy, rPoint.x, rPoint.y)
      .stroke({ color: '#666666', width: 1.5, linecap: 'round' });
    overlayGroup.line(p.cx, p.cy, f.x, f.y)
      .stroke({ color: '#8a5a00', width: 2, dasharray: '5,4', linecap: 'round' });

    var label = p.key === 'none' ? 'd > r' : (p.key === 'tangent' ? 'd = r' : 'd < r');
    var labelColor = p.key === 'none' ? ORANGE : (p.key === 'tangent' ? GREEN : RED);
    var lx = (p.cx + f.x) / 2 + (p.key === 'none' ? 14 : 12);
    var ly = (p.cy + f.y) / 2 - (p.key === 'secant' ? 10 : 3);
    addHaloText(overlayGroup, label, lx, ly, 14, 'middle', labelColor);
    addHaloText(overlayGroup, 'r', (p.cx + rPoint.x) / 2 - 9, (p.cy + rPoint.y) / 2 + 2, 12, 'middle', '#555555');
  });
}

function drawAlgebraOverlay() {
  overlayGroup.clear();

  var top = overlayGroup.rect(705, 42).move(10, 6).rx(8)
    .fill({ color: '#f8fbff', opacity: 0.82 })
    .stroke({ color: '#c9ddec', width: 1 });
  top.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Substitute the line equation into the circle equation to get a quadratic.', e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function () {
      showPopup('Algebra connection', 'Substituting y = mx + b into x² + y² = r² creates a quadratic in x. Its discriminant has the same three cases as the picture: negative, zero, or positive.');
    });

  addHaloText(overlayGroup, 'x² + y² = r²  and  y = mx + b  ⇒  Ax² + Bx + C = 0', 362.5, 23, 15, 'middle', '#222222', 'Georgia, "Times New Roman", serif');
  addHaloText(overlayGroup, 'Discriminant sign matches the number of real intersection points', 362.5, 41, 12, 'middle', '#444444');

  var cards = [
    { p: panels[0], sign: 'Δ < 0', sub: '0 real points', color: ORANGE },
    { p: panels[1], sign: 'Δ = 0', sub: '1 repeated point', color: GREEN },
    { p: panels[2], sign: 'Δ > 0', sub: '2 real points', color: RED }
  ];

  cards.forEach(function (c) {
    var x = c.p.cx - 70, y = 186;
    var card = overlayGroup.rect(140, 42).move(x, y).rx(7)
      .fill({ color: '#ffffff', opacity: 0.88 })
      .stroke({ color: c.color, width: 1.2, opacity: 0.65 });
    card.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(c.sign + ': ' + c.sub, e); })
      .on('mouseleave', function () { hideTooltip(); })
      .on('click', function () {
        showPopup(c.sign, 'This discriminant case corresponds to the diagram directly above it: ' + c.sub + ' means ' + c.p.label.toLowerCase() + '.');
      });
    addHaloText(overlayGroup, c.sign, c.p.cx, y + 17, 18, 'middle', c.color, 'Georgia, "Times New Roman", serif');
    addHaloText(overlayGroup, c.sub, c.p.cx, y + 34, 11, 'middle', '#333333');
  });
}

function renderOverlay() {
  overlayGroup.clear();
  if (currentMode === 'Distance comparison') drawDistanceOverlay();
  if (currentMode === 'Algebra connection') drawAlgebraOverlay();
}

function update_explanationMode(v) {
  currentMode = v || 'Off';
  var input = document.getElementById('explanationModeInput');
  if (input) input.value = currentMode;
  renderOverlay();
}

function toggle_explanationMode(on) {
  update_explanationMode(on ? 'Distance comparison' : 'Off');
}

function applyStep(i) {
  demoIndex = Math.max(0, Math.min(demoSteps.length - 1, i));
  var step = demoSteps[demoIndex];
  update_explanationMode(step.state.explanationMode);

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;

  var label = document.getElementById('stepLabel');
  if (label) label.textContent = (demoIndex + 1) + ' / ' + demoSteps.length;
}

function prevStep() {
  applyStep((demoIndex - 1 + demoSteps.length) % demoSteps.length);
}

function nextStep() {
  applyStep((demoIndex + 1) % demoSteps.length);
}

drawBase();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

